def _build():  # PROBLEMS from the row files; run from the repository root
    from studies.rlneurons.lib import rln4_lib
    text = {p["index"]: p for p in json.load(open(DATA["problems"]))}
    rows = {}
    for k in KEYS:
        first = {}
        for line in open(ROWS + DATA["rows"][k]):
            r = json.loads(line)
            if r["sample"] == 0 and r["problem_index"] not in first:  # the round's rule: sample 0, first row per problem
                first[r["problem_index"]] = r
        rows[k] = first
    cut = lambda s, n: s if len(s) <= n else s[:n].rsplit(" ", 1)[0] + "…"
    out, v3 = [], {k: [] for k in KEYS}
    for i in range(DATA["n"]):
        q, rs = text[i]["problem"], [rows[k][i] for k in KEYS]
        g = [rln4_lib.grade_v3(r["gold"], r["text"]) for r in rs]
        assert all(r["gold"] == text[i]["answer"] for r in rs), i
        for k, x in zip(KEYS, g):
            v3[k].append(x["score_v3"])
        out.append([i, cut(q, 260), text[i]["answer"],
                    "".join("c" if r["cap_hit"] else "r" if x["score_v3"] else "w" for r, x in zip(rs, g)),
                    "".join("1" if "Okay" in r["text"][:30] else "0" for r in rs),
                    [r["n_new"] for r in rs], [(x["extracted_v3"] or "")[:40] for x in g], [cut(r["text"], 90) for r in rs]])
    extra = {
        "v3": v3,
        "right": [sum(v3[k]) for k in KEYS],
        "okay400": [sum("Okay" in r["text"][:400] for r in rows[k].values()) for k in KEYS],
        "median_len": [round(statistics.median(r["n_new"] for r in rows[k].values() if not r["cap_hit"])) for k in KEYS],
        "median_lp": [round(statistics.median(r["mean_logprob"] for r in rows[k].values() if not r["cap_hit"] and r["mean_logprob"] is not None), 3) for k in KEYS],
    }
    return out, extra, rows


def _build1():  # PROBLEMS1 from the committed per-problem rows and the three raw files; run from the repository root
    from studies.rlneurons.lib import rln4_lib
    T = DATA["t10"]
    text = {p["index"]: p for p in json.load(open(DATA["problems"]))}
    load = lambda path: sorted(json.load(open(path)), key=lambda r: r["problem_index"])
    t13, t12 = load(T["t1_t3"]), load(T["t1_t2"])
    ck = {k: load(path) for k, path in T["cells"].items()}
    raw = {}
    for k, name in T["raw"].items():
        first = {}
        for line in open(ROWS1 + name):
            r = json.loads(line)
            if r["sample"] == 0 and r["problem_index"] not in first:
                first[r["problem_index"]] = r
        raw[k] = first
    cut = lambda s, n: s if len(s) <= n else s[:n].rsplit(" ", 1)[0] + "…"
    out, g2 = [], []
    for i in range(DATA["n"]):
        a, b, f = t13[i], t12[i], raw["s2800"][i]
        assert a["problem_index"] == b["problem_index"] == i and all(ck[k][i]["problem_index"] == i for k in ck), i
        assert (a["t1_right"], a["t1_cap_hit"]) == (b["t1_right"], b["t1_cap_hit"]), i  # Base + cue in both files
        g = rln4_lib.grade_v3(f["gold"], f["text"])
        assert f["gold"] == text[i]["answer"] and g["score_v3"] == b["t2_right"] and f["cap_hit"] == b["t2_cap_hit"], i
        g2.append(g["score_v3"])
        for k in ("s100", "s400"):
            assert raw[k][i]["text"][:30] == ck[k][i]["opening"] and raw[k][i]["gold"] == text[i]["answer"], (k, i)
        c = lambda k, start: (ck[k][i]["score_v3"], ck[k][i]["cap_hit"], ck[k][i]["n_generated"], ck[k][i]["extracted_v3"], start)
        cells = [(a["t3_right"], a["t3_cap_hit"], a["t3_generated_tokens"], a["t3_extracted_v3"], a["t3_start"]),
                 (a["t1_right"], a["t1_cap_hit"], a["t1_generated_tokens"], a["t1_extracted_v3"], a["t1_start"]),
                 c("s100", raw["s100"][i]["text"]), c("s400", raw["s400"][i]["text"]),
                 (b["t2_right"], b["t2_cap_hit"], b["t2_generated_tokens"], g["extracted_v3"], f["text"]),
                 c("s100cue", ck["s100cue"][i]["opening"]), c("s400cue", ck["s400cue"][i]["opening"])]
        out.append([i, "".join("c" if x[1] else "r" if x[0] else "w" for x in cells),
                    "".join("1" if "Okay" in x[4][:30] else "0" for x in cells),
                    [x[2] for x in cells], [(x[3] or "")[:40] for x in cells], [cut(x[4], 90) for x in cells[:5]]])
    right = {"base": [r["t3_right"] for r in t13], "cue": [r["t1_right"] for r in t13],
             "s2800": [r["t2_right"] for r in t12], **{k: [r["score_v3"] for r in ck[k]] for k in ck}}
    return out, {"right": right, "ck": ck, "t2_v3": g2}


PAGE = r"""<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Invariant: __TITLE__</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Archivo:wdth,wght@62..125,100..900&display=swap">
<style>
/* The tokens and the light of tools/architecture.py: one lit plate, glass in a dark room, porcelain on a grey table
   with a cast shadow in place of the glow. The light comes from the upper left in both. What RL brings, the 'Okay'
   opening, is lit (blue); every other opening is plain ink. */
:root {
  color-scheme: light dark;
  --paper: #eceef0; --sheet: #fbfcfc; --ink: #101820; --mute: #56636d; --faint: #606c76; --rule: #d3d9de;
  --blue: #1f43d6; --red: #c41e34;
  --glass-hi: #ffffff; --glass: #f9fafb; --glass-lo: #dfe4e8;
  --rim-a: rgba(16, 24, 32, .28); --rim-b: rgba(16, 24, 32, .58); --rim-c: rgba(16, 24, 32, .9);
  --glow: 0; --shadow: 1; --spec: 0; --bloom: .4;
  --base-tone: #6b7882; --ghost: .16;
}
@media (prefers-color-scheme: dark) {
  :root {
    --paper: #080c11; --sheet: #111922; --ink: #e9eff3; --mute: #93a1ad; --faint: #788590; --rule: #1c2630;
    --blue: #8fb1ff; --red: #ff6b7c;
    --glass-hi: #34485e; --glass: #152029; --glass-lo: #090e14;
    --rim-a: rgba(255, 255, 255, .92); --rim-b: rgba(255, 255, 255, .1); --rim-c: rgba(143, 177, 255, .45);
    --glow: 1; --shadow: 0; --spec: 1; --bloom: 1;
    --base-tone: #b7c2ca; --ghost: .2;
  }
}
* { box-sizing: border-box; }
html { background: var(--paper); }
body {
  margin: 0; color: var(--ink); background: var(--paper);
  font: 400 15px/1.5 "Archivo", ui-sans-serif, -apple-system, "Segoe UI", system-ui, sans-serif;
  font-variant-numeric: tabular-nums; -webkit-font-smoothing: antialiased;
}
button { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; text-align: left; }
a { color: inherit; }
:focus-visible { outline: 2px solid var(--blue); outline-offset: 3px; border-radius: 3px; }
.page {
  display: grid; grid-template-columns: minmax(0, 1fr) minmax(320px, 27vw); grid-template-rows: auto minmax(0, 1fr);
  gap: 0; height: 100vh; min-height: 620px; max-width: 1840px; margin: 0 auto; padding: 20px 40px 28px;
}
.top { grid-column: 1 / -1; display: flex; align-items: center; gap: 26px; font-size: 13px; padding-bottom: 16px; border-bottom: 1px solid var(--rule); }
.name { font-weight: 740; font-stretch: 122%; font-size: 15px; letter-spacing: .02em; margin: 0 6px 0 0; }
.top a { color: var(--mute); text-decoration: none; white-space: nowrap; transition: color .15s ease; }
.top a:hover { color: var(--ink); }
.top a[aria-current] { color: var(--ink); font-weight: 600; }

/* The picture: one plate with the marks, the count and the trace, and the one control under it */
.stage { min-height: 0; min-width: 0; display: flex; flex-direction: column; justify-content: center; padding: 8px 40px 0 0; }
svg { width: 100%; max-height: calc(100vh - 220px); display: block; overflow: visible; touch-action: pan-y; cursor: default; user-select: none; -webkit-user-select: none; }
svg:focus:not(:focus-visible) { outline: none; }
svg text { font-family: inherit; fill: var(--ink); font-stretch: 106%; }
svg * { pointer-events: none; }
.atmo { opacity: var(--glow); }
.shade { fill: var(--ink); opacity: calc(var(--shadow) * .17); }
.spec { opacity: var(--spec); }
.back { fill: var(--glass-lo); stroke: var(--rim-b); stroke-width: 1; }
.plate { fill: url(#body) var(--sheet); stroke: url(#rim) var(--ink); stroke-width: 1.7; }
.mk { fill: none; stroke-linecap: round; }
.mk.o { stroke: var(--blue); } .mk.x { stroke: var(--base-tone); }
.mk.w { opacity: .5; }
.mk.glow { stroke: var(--blue); opacity: calc(var(--bloom) * .13); }
.sel { fill: none; stroke: var(--ink); stroke-width: 1.8; }
.band { font-weight: 560; fill: var(--mute) !important; }
.band .n { fill: var(--ink); font-weight: 680; }
.big { font-weight: 660; letter-spacing: -.035em; font-stretch: 100%; }
.lab { fill: var(--mute) !important; font-weight: 520; }
.lab .em { fill: var(--ink); font-weight: 640; }
.rowlab { font-weight: 600; }
.rowlab.o { fill: var(--blue) !important; }
.ghost { fill: none; stroke: var(--ink); stroke-width: 1.2; opacity: var(--ghost); stroke-linecap: round; stroke-linejoin: round; }
.ref { fill: none; stroke: var(--mute); stroke-width: 1; opacity: .55; stroke-dasharray: 4 4; }
.ref.main { stroke: var(--ink); stroke-width: 1.3; opacity: .7; stroke-dasharray: 5 4; }
.lvl { fill: var(--mute) !important; font-weight: 560; }
.gapfill { fill: var(--ink); opacity: calc(.09 + var(--glow) * .07); stroke: none; }
.tl { fill: none; stroke: var(--ink); stroke-width: 2.4; stroke-linecap: round; stroke-linejoin: round; }
.tl.o { stroke: var(--blue); }
.tlglow { fill: none; stroke: var(--blue); stroke-width: 8; opacity: calc(var(--bloom) * .14); stroke-linecap: round; stroke-linejoin: round; }
.pt { fill: var(--ink); } .pt.o { fill: var(--blue); }
.smp { fill: none; stroke: var(--ink); stroke-width: 1.4; stroke-linecap: round; }
.pt.off { fill: var(--faint); opacity: .5; }
.val.far { fill: var(--faint) !important; font-weight: 450; opacity: .6; }
.cue { fill: var(--mute); stroke: none; }
.cue.on { fill: var(--ink); }
.val { font-weight: 600; }
.val.o { fill: var(--blue) !important; }
.val.dim { fill: var(--faint) !important; font-weight: 500; }
.now { stroke: var(--blue); stroke-width: 1; opacity: .35; }
.sep { stroke: var(--rule); stroke-width: 1; }
.halo { fill: var(--blue); opacity: calc(var(--bloom) * .18); }
.axis { fill: var(--faint) !important; font-weight: 520; }
.axis.on { fill: var(--ink) !important; font-weight: 680; }
.kd.o { fill: var(--blue); } .kd.x { fill: var(--base-tone); }
.control { display: flex; align-self: center; align-items: center; gap: 14px; margin-top: 16px; flex-wrap: wrap; justify-content: center; }
.switch { display: inline-flex; border: 1px solid var(--faint); border-radius: 999px; padding: 3px; }
.switch button { padding: 8px 16px; border-radius: 999px; font-weight: 600; font-size: 15px; white-space: nowrap; transition: background .15s ease, color .15s ease; }
.switch button:hover { color: var(--blue); }
.switch button[aria-pressed="true"] { background: var(--ink); color: var(--paper); }
.switch.ref button[aria-pressed="true"] { background: var(--mute); }
.switch.temp { border-color: var(--rule); margin-left: 6px; }
.switch.temp button { font-size: 13px; font-weight: 560; padding: 6px 12px; color: var(--mute); }
.switch.temp button:hover { color: var(--ink); }
.switch.temp button[aria-pressed="true"] { background: var(--rule); color: var(--ink); }
.hint { align-self: center; margin: 10px 0 0; font-size: 13px; color: var(--mute); text-align: center; }

/* One drawn entrance, then only the slow sway and what the reader changes */
@keyframes draw { from { stroke-dashoffset: 1; } to { stroke-dashoffset: 0; } }
@keyframes fade { from { opacity: 0; } }
.enter .draw { stroke-dasharray: 1; animation: draw 1.1s cubic-bezier(.6, 0, .2, 1) both; }
.enter .atmo, .enter .shade, .enter .spec, .enter .back { animation: fade 1.3s .15s both; }
.enter .marks { animation: fade .8s .4s both; }
.enter .read, .enter .trace, .enter .key { animation: fade .7s .7s both; }

/* The words */
.side {
  min-width: 0; min-height: 0; overflow-y: auto; scrollbar-width: none;
  padding: clamp(20px, 7vh, 96px) 0 0 40px; border-left: 1px solid var(--rule);
}
.problem { margin: 0; color: var(--mute); font-size: clamp(16px, 1.25vw, 20px); line-height: 1.3; max-width: 26ch; }
.say { margin: 14px 0 0; font-size: clamp(25px, 2.15vw, 40px); line-height: 1.14; font-weight: 300; font-stretch: 102%; letter-spacing: -.016em; max-width: 17ch; }
.say b { font-weight: 620; white-space: nowrap; }
.pane { margin-top: clamp(22px, 4vh, 44px); }
.more { list-style: none; margin: 0; padding: 0; border-top: 1px solid var(--rule); }
.more button { display: flex; width: 100%; justify-content: space-between; align-items: baseline; padding: 12px 0; border-bottom: 1px solid var(--rule); font-size: 17px; font-weight: 520; transition: color .15s ease; }
.more button span { color: var(--faint); font-size: 20px; line-height: 1; }
.more button:hover { color: var(--blue); }
.dhead { display: flex; align-items: baseline; justify-content: space-between; gap: 16px; padding: 0 6px 12px 0; border-bottom: 1px solid var(--ink); }
.dhead h2 { margin: 0; font-size: 17px; font-weight: 660; font-stretch: 114%; letter-spacing: .008em; }
.close { font-size: 13px; color: var(--mute); }
.close:hover { color: var(--ink); }
.lead { margin: 18px 0 0; font-size: clamp(17px, 1.3vw, 21px); line-height: 1.36; font-weight: 380; max-width: 30ch; overflow-wrap: anywhere; }
.lead.q { font-size: 15.5px; line-height: 1.45; color: var(--mute); max-width: 44ch; }
.gold { margin: 10px 0 0; font-size: 14px; color: var(--mute); }
.gold span { color: var(--ink); font-weight: 600; }
.facts { list-style: none; margin: 18px 0 0; padding: 0; font-size: 14.5px; color: var(--mute); max-width: 40ch; overflow-wrap: anywhere; }
.facts li { padding: 8px 0; border-top: 1px solid var(--rule); }
.answers { list-style: none; margin: 16px 0 0; padding: 0; font-size: 14px; color: var(--mute); max-width: 44ch; }
.answers li { padding: 9px 0 9px 12px; border-top: 1px solid var(--rule); border-left: 2px solid transparent; overflow-wrap: anywhere; }
.answers li.on { border-left-color: var(--ink); }
.answers .who { color: var(--ink); font-weight: 640; }
.answers .r { color: var(--ink); font-weight: 600; }
.answers .c { color: var(--ink); font-weight: 600; }
.answers .also { display: block; margin-top: 2px; font-size: 13px; color: var(--faint); }
.answers .also .r, .answers .also .c { color: var(--mute); }
.answers .start { display: block; margin-top: 3px; font-size: 13px; line-height: 1.45; color: var(--mute); }
.answers .start b { color: var(--blue); font-weight: 640; }
.answers .start i { font-style: normal; text-decoration: underline dotted 1px; text-underline-offset: .2em; }
.steps { display: flex; justify-content: space-between; margin-top: 14px; font-size: 13px; color: var(--mute); }
.steps button:hover { color: var(--ink); }
@media (max-width: 900px) {
  /* On a phone the order is: the problem, the finding, the picture, the depth. */
  .page { display: flex; flex-direction: column; height: auto; min-height: 0; padding: 16px 16px 40px; }
  .top { gap: 13px; padding-bottom: 12px; flex-wrap: wrap; }
  .name { font-stretch: 112%; margin-right: 0; }
  .side { display: contents; }
  .problem { order: 1; margin-top: 20px; max-width: none; }
  .say { order: 2; max-width: 22ch; }
  .stage { order: 3; margin-top: 22px; padding: 0; display: block; }
  .pane { order: 4; margin-top: 22px; }
  svg { max-height: none; }
  .control { display: flex; gap: 8px; }
  .switch { display: flex; width: 100%; }
  .switch button { flex: 1; text-align: center; padding: 10px 4px; font-size: 14px; }
  .switch.ref { width: auto; }
  .switch.ref button { padding: 8px 16px; }
  .switch.temp { width: auto; margin-left: 0; }
  .switch.temp button { padding: 8px 12px; font-size: 13px; }
}
@media (prefers-reduced-motion: reduce) {
  .enter * { animation: none !important; }
  .switch button, .more button, .top a { transition: none; }
}
.paper { margin: 18px 0 0; font-size: 15px; }
.paper a { color: var(--mute); text-decoration: none; border-bottom: 1px solid currentColor; padding-bottom: 1px; }
.paper a:hover, .paper a:focus-visible { color: inherit; }
</style>
</head>
<body>
<div class="page">
  <header class="top">
    <h1 class="name">Invariant</h1>
    <a href="/">Board</a>
    <a href="/architecture">Design</a>
    <a href="/proof">Proof</a>
    <a href="/findings" aria-current="page">Findings</a>
  </header>
  <div class="stage" id="stage">
    <svg id="svg" role="img" tabindex="0"></svg>
    <div class="control">
      <div class="switch" id="switch" role="group" aria-label="Checkpoint of RL training">
        <button data-k="0" aria-pressed="false">Base</button>
        <button data-k="2" aria-pressed="false">Step 100</button>
        <button data-k="3" aria-pressed="false">Step 400</button>
        <button data-k="4" aria-pressed="false">Step 2,800</button>
      </div>
      <div class="switch ref" role="group" aria-label="Reference">
        <button data-k="1" aria-pressed="false">Base + cue</button>
      </div>
      <div class="switch temp" role="group" aria-label="Temperature">
        <button data-t="0" aria-pressed="false">T 0.6</button>
        <button data-t="1" aria-pressed="false">T 1.0</button>
      </div>
    </div>
    <p class="hint">Base + cue: the base model with RL's three-token opening placed in front. Step 2,800 is the released RL model.<br>Each mark is one problem in one sample; at T 1.0 the counts of right answers are means of 4 samples (Base: one). Click a mark to see a problem.</p>
  </div>
  <div class="side">
    <p class="problem" id="problem"></p>
    <p class="say" id="say"></p>
    <div class="pane" id="pane" aria-live="polite"></div>
    <p class="paper"><a href="/paper/the-first-hundred-steps.pdf">Read the paper (PDF) ›</a></p>
  </div>
</div>
<script>
const C = __CONFIG__, D = C.data, $ = id => document.getElementById(id);
const still = matchMedia("(prefers-reduced-motion: reduce)"), narrow = matchMedia("(max-width: 900px)");
const esc = s => String(s ?? "").replace(/[&<>"]/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[c]);
const RAD = Math.PI / 180, f = n => n.toFixed(1), mix = (a, b, q) => a + (b - a) * q;
const ease = p => p < .5 ? 2 * p * p : 1 - (-2 * p + 2) ** 2 / 2, clamp = (v, a, b) => Math.min(b, Math.max(a, v));
const fmt = n => Math.round(n).toLocaleString("en-US");
/* At T 1.0 the counts of right answers of Base + cue and of steps 100, 400 and 2,800 are means of 4 samples (D.samples[k]),
   written with one decimal; Base and every count at T 0.6 are one sample. */
const has4 = (T, k) => T === 1 && !!D.samples[k], fr = (v, dec) => dec ? v.toFixed(1) : fmt(v);

/* The five settings, in the order of every list of a problem: Base, Base + cue, step 100, step 400, step 2,800. The
   training path is 0, 2, 3, 4; Base + cue (1) is the reference. At T 1.0 two more settings, the cue on step 100 (5) and
   on step 400 (6), are shown only in a problem's detail. Each problem has its rows at T 0.6 (index 0 of o, ok, len, ans,
   start) and at T 1.0 (index 1). A problem's outcome at a setting is r (finished right), w (finished wrong) or c (cut
   off); its opening is 1 when 'Okay' is in the first 30 characters. */
const KEYS = ["base", "cue", "s100", "s400", "s2800"];
const NAME = ["Base", "Base + cue", "Step 100", "Step 400", "Step 2,800", "Step 100 + cue", "Step 400 + cue"];
const PATH = [0, 2, 3, 4], AT = ["at Base", "with the cue", "at step 100", "at step 400", "at step 2,800"];
const TEMP = ["T 0.6", "T 1.0"], TOPP = ["top-p 0.95", "top-p 1.0"];
const N = D.n, BANDS = ["r", "w", "c"];
const PR = C.problems.map(([i, q, gold, o, ok, len, ans, start], j) => {
  const [, o1, ok1, len1, ans1, start1] = C.problems1[j];
  return { i, q, gold, o: [o, o1], ok: [ok, ok1], len: [len, len1], ans: [ans, ans1], start: [start, start1] };
});
const count = (T, k, test) => PR.reduce((s, p) => s + (test(p, T, k) ? 1 : 0), 0);
const both = test => [0, 1].map(T => KEYS.map((_, k) => count(T, k, test)));
const SERIES = [  // the three rows of the trace: name, count per temperature and setting, scale [low, high]
  { name: "Right answers", v: D.right, lo: 200, hi: 480, main: true },
  { name: "Open with 'Okay'", v: both((p, T, k) => p.ok[T][k] === "1"), lo: 0, hi: N, o: true },
  { name: `Cut off at ${fmt(D.cap)} tokens`, v: both((p, T, k) => p.o[T][k] === "c"), lo: 0, hi: 125 },
];
const val = (s, k, q) => mix(s.v[0][k], s.v[1][k], q);  // q: 0 at T 0.6, 1 at T 1.0, between while it changes
/* The order inside a band: answers that open with 'Okay' first, then the problems right at more settings, then by index,
   so the blue marks gather at the start of each band and a band fills from its first row. */
const EASE_ORDER = PR.map(p => [...(p.o[0] + p.o[1].slice(0, 5))].filter(x => x === "r").length);
const S = { k: 2, T: 1, open: null, g: null, el: {}, shown: {}, t: 0, last: 0, t0: -1e9, from: [], to: [], fromOk: [], toOk: [],
  fromBand: [], toBand: [], rank: [], c0: [0, 0, 0, 0, 0], c1: [0, 0, 0, 0, 0], p0: 1, p1: 1, q0: 1, q1: 1, pos: [], touched: false };

/* Geometry, in a small 3D space around the plate's centre (x right, y down, z toward the viewer). bands: the three
   outcome bands of marks (label line, first row); read: the large count and its lines; trace: three rows and the axis. */
function geo() {
  if (narrow.matches) {
    const g = { w: 480, h: 1490, cx: 240, cy: 745, D: 2400, a: [6, 8, 474, 1482], r: 22, deep: 30, blur: 12,
      cols: 24, pitch: 17, gx: 44, d: [9, 6.4, 10], fs: 18, fb: 104,
      bigX: 36, bigY: 118, labY: [154, 178, 202], bandTop: 262, bandGap: 50, keyY: 0,
      tx: [168, 66, 254, 342, 428], rowH: [120, 56, 56], fv: 17, phone: true };
    return lay(g);
  }
  const g = { w: 1000, h: 600, cx: 500, cy: 300, D: 2200, a: [24, 18, 976, 582], r: 30, deep: 40, blur: 16,
    cols: 32, pitch: 13, gx: 62, d: [8, 5.4, 9], fs: 15, fb: 112,
    bigX: 540, bigY: 118, labY: [148, 168, 188], bandTop: 64, bandGap: 34, keyY: 0,
    tx: [650, 558, 740, 830, 916], rowY: [312, 430, 516], rowH: [100, 36, 36], axisY: 568, fv: 13.5 };
  return lay(g);
}
function lay(g) {  // band rows sized for the largest count each band reaches at any setting and temperature
  let y = g.bandTop;
  g.band = BANDS.map((b, j) => {
    const most = Math.max(...both((p, T, k) => p.o[T][k] === b).flat()), rows = Math.ceil(most / g.cols);
    const out = { lab: y, y0: y + g.fs * 1.25, rows };
    y = out.y0 + (rows - 1) * g.pitch + g.bandGap;
    return out;
  });
  g.keyY = y - g.bandGap + g.fs * 2.4;
  if (g.phone) {  // on a phone the trace sits under the marks
    let top = g.keyY + 64;
    g.rowY = g.rowH.map(h => { top += g.fv * 2.5 + 16; const c = top + h / 2; top += h + 22; return c; });
    g.axisY = top + 34;
    g.h = g.axisY + 44; g.cy = g.h / 2; g.a = [6, 8, 474, g.h - 8];
  }
  return g;
}
const V = { c1: 1, s1: 0, c2: 1, s2: 0, px: 0, py: 0, tx: 0, ty: 0 };
function aim(yaw, pitch) { V.c1 = Math.cos(yaw * RAD); V.s1 = Math.sin(yaw * RAD); V.c2 = Math.cos(pitch * RAD); V.s2 = Math.sin(pitch * RAD); }
function proj(g, x, y, z) {
  const X = x - g.cx, Y = y - g.cy, x1 = X * V.c1 + z * V.s1, z1 = z * V.c1 - X * V.s1;
  const y1 = Y * V.c2 - z1 * V.s2, k = g.D / (g.D - (z1 * V.c2 + Y * V.s2));
  return [g.cx + x1 * k, g.cy + y1 * k];
}
function rounded(g, [x0, y0, x1, y1], r, z) {  // a rounded rectangle at depth z
  const p = [], corner = (cx, cy, a0) => { for (let i = 0; i <= 6; i++) p.push(proj(g, cx + r * Math.cos((a0 + 15 * i) * RAD), cy + r * Math.sin((a0 + 15 * i) * RAD), z)); };
  corner(x1 - r, y0 + r, -90); corner(x1 - r, y1 - r, 0); corner(x0 + r, y1 - r, 90); corner(x0 + r, y0 + r, 180);
  return "M" + p.map(q => f(q[0]) + " " + f(q[1])).join("L") + "Z";
}
const rowY = (g, j, v) => { const s = SERIES[j], h = g.rowH[j]; return g.rowY[j] + h / 2 - (v - s.lo) / (s.hi - s.lo) * h; };

function build() {
  const g = S.g = geo(), svg = $("svg"), [ax0, ay0, ax1, ay1] = g.a, aw = ax1 - ax0, ah = ay1 - ay0;
  const stop = (at, color, alpha) => `<stop offset="${at}" style="stop-color:${color}${alpha == null ? "" : ";stop-opacity:" + alpha}"/>`;
  svg.setAttribute("viewBox", `0 0 ${g.w} ${g.h}`);
  const marks = BANDS.map((b, j) => ["o", "x"].map(t => `<path class="mk ${t}${b === "w" ? " w" : ""}" id="m${b}${t}" stroke-width="${b === "c" ? 3 : g.d[j]}"/>`).join("")).join("");
  svg.innerHTML = "<defs>" +
    `<radialGradient id="body" cx=".3" cy=".22" r=".95">${stop(0, "var(--glass-hi)")}${stop(.46, "var(--glass)")}${stop(1, "var(--glass-lo)")}</radialGradient>` +
    `<linearGradient id="rim" x1=".06" y1=".04" x2=".94" y2=".96">${stop(0, "var(--rim-a)")}${stop(.56, "var(--rim-b)")}${stop(1, "var(--rim-c)")}</linearGradient>` +
    `<radialGradient id="atmo">${stop(.5, "var(--blue)", .2)}${stop(.72, "var(--blue)", .06)}${stop(1, "var(--blue)", 0)}</radialGradient>` +
    `<radialGradient id="spec">${stop(0, "#fff", .2)}${stop(1, "#fff", 0)}</radialGradient>` +
    `<filter id="soft" x="-20%" y="-20%" width="140%" height="150%"><feGaussianBlur stdDeviation="${g.blur}"/></filter></defs>` +
    `<ellipse class="atmo" cx="${g.cx}" cy="${g.cy}" rx="${f(aw * .8)}" ry="${f(ah * .9)}" fill="url(#atmo)"/>` +
    `<rect class="shade" x="${f(ax0 + aw * .012)}" y="${f(ay0 + ah * .04)}" width="${aw}" height="${ah}" rx="${g.r}" filter="url(#soft)"/>` +
    `<path class="back" id="back"/><path class="plate draw" id="plate" pathLength="1"/>` +
    `<ellipse class="spec" cx="${f(ax0 + aw * .3)}" cy="${f(ay0 + ah * .24)}" rx="${f(aw * .3)}" ry="${f(ah * .2)}" transform="rotate(-14 ${f(ax0 + aw * .3)} ${f(ay0 + ah * .24)})" fill="url(#spec)"/>` +
    `<g class="marks"><path class="mk glow" id="mg" stroke-width="${g.d[0] + 7}"/>${marks}<circle class="sel" id="sel" r="0"/>` +
    BANDS.map(b => `<text class="band" id="b${b}" font-size="${g.fs}"><tspan class="n" id="bn${b}"></tspan><tspan id="bt${b}"></tspan></text>`).join("") + `</g>` +
    `<g class="key"><circle class="kd o" id="ko" r="${g.d[0] / 2}"/><text class="lab" id="kto" font-size="${g.fs}">Opens with 'Okay'</text>` +
    `<circle class="kd x" id="kx" r="${g.d[0] / 2}"/><text class="lab" id="ktx" font-size="${g.fs}">Other opening</text></g>` +
    `<g class="read"><text class="big" id="big" font-size="${g.fb}"></text>` +
    [0, 1, 2].map(k => `<text class="lab" id="bl${k}" font-size="${g.fs}"></text>`).join("") + `</g>` +
    `<g class="trace"><path class="now" id="now"/><path class="sep" id="sep"/>` +
    SERIES.map((s, j) => `<text class="rowlab${s.o ? " o" : ""}" id="rl${j}" font-size="${g.fs}">${esc(s.name)}${s.main ? `<tspan class="lab" id="rlx"></tspan>` : ""}</text>` +
      `<path class="ref${s.main ? " main" : ""}" id="rf${j}"/>${s.main ? `<text class="lvl" id="lv" font-size="${g.fv}" text-anchor="end">Base + cue</text><path class="gapfill" id="gf"/>` : ""}<path class="ghost" id="gh${j}"/>${s.main ? [1, 2, 3, 4].map(k => `<path class="smp" id="sm${k}"/>`).join("") : ""}${s.o ? `<path class="tlglow" id="tg${j}"/>` : ""}<path class="tl${s.o ? " o" : ""}" id="tl${j}"/>` +
      `<circle class="halo" id="ha${j}" r="0"/><circle class="cue" id="cu${j}" r="${g.fv * .34}"/>` +
      PATH.map(k => `<circle class="pt${s.o ? " o" : ""}" id="pt${j}_${k}" r="${g.fv * .3}"/>`).join("") +
      KEYS.map((_, k) => `<text class="val${s.o ? " o" : ""}" id="v${j}_${k}" font-size="${g.fv}" text-anchor="middle"></text>`).join("")).join("") +
    KEYS.map((_, k) => `<text class="axis" id="ax${k}" font-size="${g.fv}" text-anchor="middle">${k === 0 || k === 1 ? NAME[k] : narrow.matches ? NAME[k].replace("Step ", "") : NAME[k]}</text>`).join("") +
    `</g>`;
  S.el = {}; S.shown = {};
  svg.querySelectorAll("[id]").forEach(e => { S.el[e.id] = e; });
}

/* Where each mark is in its change: it travels from its old place to its new one along an eased path, lifting toward the
   viewer on the way; its look (outcome and opening) switches halfway. A change starts at t0, 0.5 ms later per place in
   the new order, and takes 0.64 s. */
function slot(g, band, s) {
  const b = g.band[BANDS.indexOf(band)], col = s % g.cols, row = (s - col) / g.cols;
  return [g.gx + col * g.pitch, b.y0 + row * g.pitch];
}
function markAt(k, now) {
  const p = clamp((now - S.t0 - .5 * S.rank[k]) / 640, 0, 1), e = ease(p), a = S.from[k], b = S.to[k];
  const moved = a[0] !== b[0] || a[1] !== b[1], far = S.fromBand[k] !== S.toBand[k] || S.fromOk[k] !== S.toOk[k];
  return { x: mix(a[0], b[0], e), y: mix(a[1], b[1], e), z: moved ? (far ? 30 : 8) * Math.sin(Math.PI * p) : 0,
    band: p < .5 ? S.fromBand[k] : S.toBand[k], ok: p < .5 ? S.fromOk[k] : S.toOk[k] };
}
function place(t, now) {
  const g = S.g, E = S.el, at = (el, q, dy) => { el.setAttribute("x", f(q[0])); el.setAttribute("y", f(q[1] + (dy || 0))); };
  const text = (id, v) => { if (S.shown[id] !== v) E[id].textContent = S.shown[id] = v; };
  E.back.setAttribute("d", rounded(g, g.a, g.r, -g.deep));
  E.plate.setAttribute("d", rounded(g, g.a, g.r, 0));

  // The marks, batched into six paths by look (outcome x opening), so a frame sets a few attributes, not one per mark.
  const d = {}, half = g.pitch * .33;
  BANDS.forEach(b => { d[b + "o"] = ""; d[b + "x"] = ""; });
  let glow = "";
  for (let k = 0; k < PR.length; k++) {
    const m = markAt(k, now), q = proj(g, m.x, m.y, 6 + m.z), key = m.band + (m.ok ? "o" : "x");
    S.pos[k] = q;
    const s = m.band === "c" ? `M${f(q[0] - half)} ${f(q[1])}h${f(2 * half)}` : `M${f(q[0])} ${f(q[1])}h0`;
    d[key] += s;
    if (m.ok && m.band === "r") glow += s;
  }
  for (const key in d) E["m" + key].setAttribute("d", d[key]);
  E.mg.setAttribute("d", glow);
  const sel = S.open && S.open[0] === "p" ? PR.findIndex(p => "p" + p.i === S.open) : -1;
  if (sel >= 0) { E.sel.setAttribute("cx", f(S.pos[sel][0])); E.sel.setAttribute("cy", f(S.pos[sel][1])); E.sel.setAttribute("r", f(g.pitch * .62)); }
  else E.sel.setAttribute("r", "0");

  // Every number counts while the marks travel and stops with them; the words of the new state arrive with its numbers.
  const e = ease(clamp((now - S.t0) / 900, 0, 1)), c = S.c0.map((v, i) => mix(v, S.c1[i], e)), done = e > .98;
  const kNow = done ? S.k : S.kFrom, TNow = done ? S.T : S.TFrom, tq = mix(S.q0, S.q1, e);
  const word = ["finished right", "finished wrong", `cut off at ${fmt(D.cap)} tokens`];
  BANDS.forEach((b, j) => {
    text("bn" + b, fmt(c[j + 1])); text("bt" + b, " " + word[j]);
    at(E["b" + b], proj(g, g.gx - g.d[0] / 2, g.band[j].lab, 4));
  });
  const ky = g.keyY;
  [["ko", "kto", 0], ["kx", "ktx", narrow.matches ? 190 : 160]].forEach(([dot, lab, dx]) => {
    const q = proj(g, g.gx + dx, ky, 4);
    E[dot].setAttribute("cx", f(q[0])); E[dot].setAttribute("cy", f(q[1]));
    at(E[lab], [q[0] + g.fs * .8, q[1]], g.fs * .35);
  });
  text("big", fr(c[0], has4(S.T, S.k)));
  at(E.big, proj(g, g.bigX, g.bigY, 10));
  const kr = kNow === 1 ? 0 : 1, sm = D.samples[kNow];
  const four = has4(TNow, kNow), other = `${NAME[kr]}: ${fr(D.right[TNow][kr], has4(TNow, kr))}`;
  text("bl0", `of ${N} MATH-500 problems right ${AT[kNow]}`);
  text("bl1", `at ${TEMP[TNow]}, ` + (four ? "the mean of 4 samples:" : "in one sample."));
  text("bl2", four ? `${sm.join(", ")}. ${other}${has4(TNow, kr) ? "" : ", one sample"}.` : other + (has4(TNow, kr) ? ", the mean of 4 samples." : ", one sample."));
  [0, 1, 2].forEach(k => at(E["bl" + k], proj(g, g.bigX + 4, g.labY[k], 10)));

  // The trace: each row its own scale, the values printed. The training line draws on to the chosen step (p, 0 to 3 along
  // Base, 100, 400, 2,800); Base + cue is a hollow point with a dashed level across the row, named on the row of right
  // answers. When the temperature changes, every value moves from its T 0.6 count to its T 1.0 count or back (q).
  const pr = mix(S.p0, S.p1, e), X = k => g.tx[k];
  const line = pts => "M" + pts.map(q => f(q[0]) + " " + f(q[1])).join("L");
  SERIES.forEach((s, j) => {
    const P = k => proj(g, X(k), rowY(g, j, val(s, k, tq)), 10);
    at(E["rl" + j], proj(g, g.tx[1] - (narrow.matches ? 22 : 18), g.rowY[j] - g.rowH[j] / 2 - g.fv * 2.5, 10));
    E["gh" + j].setAttribute("d", line(PATH.map(P)));
    const cy = rowY(g, j, val(s, 1, tq));
    E["rf" + j].setAttribute("d", line([proj(g, X(1), cy, 10), proj(g, X(4) + 12, cy, 10)]));
    if (s.main) {  // the level is named, and the part of the line above it from step 100 on is shaded
      at(E.lv, proj(g, X(4) + 12, cy, 10), g.fv * 1.25);
      const m = [], y = k => Math.min(cy, rowY(g, j, val(s, k, tq)));
      for (let i = 1; i < PATH.length; i++) {
        if (pr >= i) m.push([X(PATH[i]), y(PATH[i])]);
        else if (pr > i - 1 && i > 1) { const u = pr - (i - 1); m.push([mix(X(PATH[i - 1]), X(PATH[i]), u), mix(y(PATH[i - 1]), y(PATH[i]), u)]); break; }
        else break;
      }
      E.gf.setAttribute("d", m.length < 2 ? "" : line([...m, [m[m.length - 1][0], cy], [m[0][0], cy]].map(p => proj(g, p[0], p[1], 10))) + "Z");
    }
    const pts = [P(0)];
    for (let i = 1; i < PATH.length; i++) {
      if (pr >= i) pts.push(P(PATH[i]));
      else if (pr > i - 1) { const a = P(PATH[i - 1]), b = P(PATH[i]), u = pr - (i - 1); pts.push([mix(a[0], b[0], u), mix(a[1], b[1], u)]); break; }
      else break;
    }
    E["tl" + j].setAttribute("d", line(pts));
    if (E["tg" + j]) E["tg" + j].setAttribute("d", line(pts));
    PATH.forEach((k, i) => {
      const el = E[`pt${j}_${k}`], q = P(k), on = pr >= i - .02;
      el.setAttribute("cx", f(q[0])); el.setAttribute("cy", f(q[1]));
      el.setAttribute("class", `pt${s.o ? " o" : ""}${on ? "" : " off"}`);
      el.setAttribute("r", f(g.fv * (k === kNow ? .42 : .3)));
      const v = E[`v${j}_${k}`];
      at(v, q, -g.fv * .75);
      text(`v${j}_${k}`, fr(val(s, k, tq), s.main && has4(S.T, k)));
      v.setAttribute("class", `val${s.o && on ? " o" : ""}${k === kNow ? "" : on ? " dim" : " far"}`);
    });
    const cq = proj(g, X(1), cy, 10);
    E["cu" + j].setAttribute("cx", f(cq[0])); E["cu" + j].setAttribute("cy", f(cq[1]));
    E["cu" + j].setAttribute("class", "cue" + (kNow === 1 ? " on" : ""));
    at(E[`v${j}_1`], cq, -g.fv * .75); text(`v${j}_1`, fr(val(s, 1, tq), s.main && has4(S.T, 1)));
    if (s.main) text("rlx", has4(TNow, 2) ? "  ·  ticks: the 4 samples" : "");
    if (s.main) [1, 2, 3, 4].forEach(k => {  // the 4 samples at T 1.0: faint ticks left of the point, and their range
      const x = X(k) - g.fv * 1.15, ys = D.samples[k].map(v => rowY(g, j, v)), w = g.fv * .34;
      const lo = Math.max(...ys), hi = Math.min(...ys), on = k === 1 || pr >= PATH.indexOf(k) - .02, el = E["sm" + k];
      const seg = (x0, y0, x1, y1) => { const a = proj(g, x0, y0, 10), b = proj(g, x1, y1, 10); return `M${f(a[0])} ${f(a[1])}L${f(b[0])} ${f(b[1])}`; };
      el.setAttribute("d", seg(x, lo, x, hi) + ys.map(y => seg(x - w, y, x + w, y)).join(""));
      el.setAttribute("opacity", f(tq * (on ? .62 : .22)));
    });
    E[`v${j}_1`].setAttribute("class", "val" + (kNow === 1 ? "" : " dim"));
    // the halo marks the chosen point and breathes slowly
    const hq = kNow === 1 ? cq : P(kNow);
    E["ha" + j].setAttribute("cx", f(hq[0])); E["ha" + j].setAttribute("cy", f(hq[1]));
    E["ha" + j].setAttribute("r", f(g.fv * (still.matches ? .9 : .9 + .12 * Math.sin(t * 1.4))));
  });
  const nx = X(kNow), top = proj(g, nx, g.rowY[0] - g.rowH[0] / 2 - 4, 10), bot = proj(g, nx, g.axisY - g.fv * 1.2, 10);
  E.now.setAttribute("d", `M${f(top[0])} ${f(top[1])}L${f(bot[0])} ${f(bot[1])}`);
  const sx = (X(0) + X(1)) / 2, s0 = proj(g, sx, g.rowY[0] - g.rowH[0] / 2, 10), s1 = proj(g, sx, g.axisY + 4, 10);  // reference | training
  E.sep.setAttribute("d", `M${f(s0[0])} ${f(s0[1])}L${f(s1[0])} ${f(s1[1])}`);
  KEYS.forEach((_, k) => { at(E["ax" + k], proj(g, X(k), g.axisY, 10)); E["ax" + k].setAttribute("class", "axis" + (k === kNow ? " on" : "")); });
}

/* Always on: the plate sways by a few degrees and leans toward the mouse. About 30 frames a second. With reduced motion
   the page shows one still frame per state. */
function frame(now) {
  requestAnimationFrame(frame);
  if (still.matches || now - S.last < 30) return;
  S.last = now;
  const t = S.t = now / 1000;
  V.px += (V.tx - V.px) * .1; V.py += (V.ty - V.py) * .1;
  aim(4 * Math.sin(t * .13) + 3.5 * V.px, 2 * Math.sin(t * .09) - 2 * V.py);
  place(t, now);
}
function layout(k, T) {  // each problem's band and place at setting k and temperature T
  const g = S.g, band = PR.map(p => p.o[T][k]), ok = PR.map(p => p.ok[T][k] === "1"), pos = [], rank = [];
  let r = 0;
  BANDS.forEach(b => {
    const ids = PR.map((p, j) => j).filter(j => band[j] === b)
      .sort((x, y) => ok[y] - ok[x] || EASE_ORDER[y] - EASE_ORDER[x] || PR[x].i - PR[y].i);
    ids.forEach((j, s) => { pos[j] = slot(g, b, s); rank[j] = r++; });
  });
  return { band, ok, pos, rank };
}
function counts(k, T) { return [SERIES[0].v[T][k], ...BANDS.map(b => count(T, k, p => p.o[T][k] === b)), SERIES[1].v[T][k]]; }
function setState(k, opts = {}) {
  const now = performance.now(), quick = still.matches || opts.instant, T = opts.T ?? S.T;
  const e = ease(clamp((now - S.t0) / 900, 0, 1)), L = layout(k, T);
  const cur = quick ? null : PR.map((p, j) => markAt(j, now));
  S.from = quick ? L.pos.slice() : cur.map(m => [m.x, m.y]);
  S.fromBand = quick ? L.band.slice() : cur.map(m => m.band);
  S.fromOk = quick ? L.ok.slice() : cur.map(m => m.ok);
  S.to = L.pos; S.toBand = L.band; S.toOk = L.ok; S.rank = L.rank;
  const c = S.c0.map((v, i) => mix(v, S.c1[i], e)), p = mix(S.p0, S.p1, e), q = mix(S.q0, S.q1, e);
  S.c1 = counts(k, T); S.c0 = quick ? S.c1.slice() : c;
  S.p1 = k === 1 ? Math.round(p) : PATH.indexOf(k); S.p0 = quick ? S.p1 : p;
  S.q1 = T; S.q0 = quick ? T : q;
  S.kFrom = quick ? k : S.k; S.TFrom = quick ? T : S.T;
  S.k = k; S.T = T;
  S.t0 = quick ? -1e9 : now;
  document.querySelectorAll("[data-k]").forEach(b => b.setAttribute("aria-pressed", Number(b.dataset.k) === k));
  document.querySelectorAll("[data-t]").forEach(b => b.setAttribute("aria-pressed", Number(b.dataset.t) === T));
  const [right, r, w, cut, ok] = S.c1;
  $("svg").setAttribute("aria-label", `${NAME[k]}, ${TEMP[T]}: ${fr(right, has4(T, k))} of ${N} MATH-500 problems right` +
    (has4(T, k) ? `, the mean of 4 samples (${D.samples[k].join(", ")}). ` : `, one sample. `) +
    `Base + cue: ${fr(D.right[T][1], has4(T, 1))} right. ${N} marks, one per problem, from one sample: ` +
    `${ok} open with 'Okay'; ${r} finished right, ${w} finished wrong, ${cut} cut off at ${fmt(D.cap)} tokens. ` +
    `Arrow keys step through training; Enter opens a problem.`);
  if (still.matches) { aim(0, 0); place(0, now); }
  if (S.open && S.open[0] === "p") pane();
}

/* The side column: the five panels, or one problem's answers at every setting. */
function opening(p, T, k) {
  let s = esc(p.start[T][k].replace(/\s+/g, " ").trim());
  if (!s) return "The answer is empty.";
  if (k === 1) s = s.replace(/^line! Okay/, "<i>line! Okay</i>");  // the cue, placed before the model writes
  else s = s.replace(/Okay/, "<b>Okay</b>");
  return `“${s}”`;
}
function problemPane(j) {
  const p = PR[j];
  const said = (T, k, full) => p.o[T][k] === "c" ? `<span class="c">cut off</span> at ${fmt(D.cap)} tokens`
    : `<span class="${p.o[T][k] === "r" ? "r" : ""}">${p.o[T][k] === "r" ? "right" : "wrong"}</span> in ${fmt(p.len[T][k])} tokens` +
      (!full ? "" : p.ans[T][k] ? `, answer <span data-math>${esc(p.ans[T][k])}</span>` : ", no answer found");
  const order = [0, 1, 2, 5, 3, 6, 4];  // the cue on steps 100 and 400 exists only at T 1.0
  const line = k => {
    const Ts = k > 4 ? [1] : [S.T, 1 - S.T];
    return `<li class="${k === S.k ? "on" : ""}"><span class="who">${NAME[k]}</span>, ` +
      Ts.map((T, n) => n ? `<span class="also">${TEMP[T]}: ${said(T, k, false)}.</span>` : `${TEMP[T]}: ${said(T, k, true)}.`).join(" ") +
      (k > 4 ? "" : `<span class="start" data-math>${opening(p, S.T, k)}</span>`) + `</li>`;
  };
  return `<div class="dhead"><h2>MATH-500, problem ${p.i}</h2><button class="close" data-open="">Close</button></div>` +
    `<p class="lead q" data-math>${esc(p.q)}</p>` +
    `<p class="gold">Reference answer: <span data-math>${esc(p.gold)}</span></p>` +
    `<ul class="answers">${order.map(line).join("")}</ul>` +
    `<p class="gold">Each line is one stored answer per temperature (the sample the marks draw); the quoted text is the first characters of the ${TEMP[S.T]} answer as written; underlined: the cue.</p>` +
    `<div class="steps"><button data-step="-1">‹ Previous problem</button><button data-step="1">Next problem ›</button></div>`;
}
function pane() {
  const p = C.panels.find(p => p[0] === S.open), j = S.open && S.open[0] === "p" ? PR.findIndex(q => "p" + q.i === S.open) : -1;
  $("pane").innerHTML = j >= 0 ? problemPane(j) : p
    ? `<div class="dhead"><h2>${esc(p[1])}</h2><button class="close" data-open="">Close</button></div><p class="lead">${esc(p[2])}</p>` +
      `<ul class="facts">${p[3].map(x => `<li>${esc(x)}</li>`).join("")}</ul>`
    : `<ul class="more">${C.panels.map(p => `<li><button data-open="${p[0]}">${esc(p[1])}<span aria-hidden="true">›</span></button></li>`).join("")}</ul>`;
}
/* The state and what is open are one value in the address: #<state>, then /<panel> or /p<problem>. */
function address(push) {
  const parts = [S.k === 2 ? "" : KEYS[S.k], S.T === 1 ? "" : "t0.6", S.open || ""].filter(Boolean);
  const url = parts.length ? "#" + parts.join("/") : location.pathname;
  push ? history.pushState(null, "", url) : history.replaceState(null, "", url);
}
function fromHash(first) {
  const parts = decodeURIComponent(location.hash.slice(1)).split("/"), k0 = KEYS.indexOf(parts[0]), k = k0 >= 0 ? k0 : 2;
  const T = parts.includes("t0.6") ? 0 : 1;
  const rest = parts.find(x => C.panels.some(p => p[0] === x) || PR.some(p => "p" + p.i === x));
  S.open = rest || null;
  if (first === true) {
    // With an empty address the page opens on Base and steps to step 100 by itself, so the opening arrives in view.
    if (k0 < 0 && !still.matches) {
      setState(0, { instant: true, T });
      setTimeout(() => { if (!S.touched) setState(2); }, 1300);
    } else setState(k, { instant: true, T });
  } else if (k !== S.k || T !== S.T) setState(k, { T });
  pane();
}
const show = () => { if (narrow.matches) $("pane").scrollIntoView({ behavior: still.matches ? "auto" : "smooth", block: "start" }); };
function open(key) {
  const was = S.open;
  S.open = key || null;
  address(true);
  pane();
  if (still.matches) place(0, performance.now());
  const to = $("pane").querySelector(key ? ".close" : `[data-open="${was}"]`);
  if (to) to.focus({ preventScroll: true });
  else if (!key) $("svg").focus({ preventScroll: true });
}
function go(k) { S.touched = true; if (k !== S.k) { setState(k); address(false); } }
function goT(T) { S.touched = true; if (T !== S.T) { setState(S.k, { T }); address(false); } }

/* The picture's controls: click a mark to open its problem. */
const svg = $("svg");
function svgPoint(e) { const m = svg.getScreenCTM().inverse(); return [m.a * e.clientX + m.c * e.clientY + m.e, m.b * e.clientX + m.d * e.clientY + m.f]; }
function nearest([x, y]) {
  let best = -1, bd = (S.g.pitch * .75) ** 2;
  S.pos.forEach((q, k) => { const d = (q[0] - x) ** 2 + (q[1] - y) ** 2; if (d < bd) { bd = d; best = k; } });
  return best;
}
svg.addEventListener("pointermove", e => { if (e.pointerType === "mouse") svg.style.cursor = nearest(svgPoint(e)) >= 0 ? "pointer" : "default"; });
svg.addEventListener("click", e => {
  const k = nearest(svgPoint(e));
  if (k >= 0) { S.touched = true; open("p" + PR[k].i); show(); }
});
document.addEventListener("click", e => {
  const b = e.target.closest("[data-k]"), o = e.target.closest("[data-open]"), s = e.target.closest("[data-step]");
  const t = e.target.closest("[data-t]");
  if (b) go(Number(b.dataset.k));
  if (t) goT(Number(t.dataset.t));
  if (o) open(o.dataset.open);
  if (s) {
    const j = PR.findIndex(p => "p" + p.i === S.open), n = (j + Number(s.dataset.step) + PR.length) % PR.length;
    open("p" + PR[n].i);
    $("pane").querySelector(`[data-step="${s.dataset.step}"]`).focus({ preventScroll: true });
  }
});
document.addEventListener("keydown", e => {
  if (e.metaKey || e.ctrlKey || e.altKey) return;
  if (e.key === "Escape" && S.open) open("");
  if ((e.key === "ArrowRight" || e.key === "ArrowLeft") && !/INPUT|TEXTAREA/.test(document.activeElement.tagName)) {
    const i = S.k === 1 ? 0 : PATH.indexOf(S.k), n = clamp(i + (e.key === "ArrowRight" ? 1 : -1), 0, PATH.length - 1);
    go(PATH[n]);
  }
  if (e.key === "Enter" && document.activeElement === svg) {  // the first mark of the first band
    e.preventDefault();
    const j = S.rank.indexOf(0);
    open("p" + PR[j].i);
    show();
  }
});
addEventListener("hashchange", fromHash);
addEventListener("popstate", fromHash);
narrow.addEventListener("change", () => { build(); setState(S.k, { instant: true }); place(S.t, performance.now()); });
still.addEventListener("change", () => { if (still.matches) { setState(S.k, { instant: true }); aim(0, 0); place(0, performance.now()); } });
const stage = $("stage");
stage.addEventListener("pointermove", e => {
  if (e.pointerType !== "mouse" || still.matches) return;
  const b = stage.getBoundingClientRect();
  V.tx = 2 * (e.clientX - b.left) / b.width - 1; V.ty = 2 * (e.clientY - b.top) / b.height - 1;
});
stage.addEventListener("pointerleave", () => { V.tx = V.ty = 0; });

$("problem").textContent = C.problem;
$("say").innerHTML = esc(C.line).replace(/(?<![\w-])(\d+(?:[.,]\d+)*(?: ?%)?)/g, "<b>$1</b>");
build();
aim(0, 0);
fromHash(true);
place(0, performance.now());
if (!still.matches) {
  svg.classList.add("enter");
  setTimeout(() => svg.classList.remove("enter"), 2200);
}
requestAnimationFrame(frame);
</script>
</body>
</html>
"""

# The icon of this finding's tile on /findings (tools/findings.py says how it is called): the page's own picture,
# reduced. A glass slab with a grid of marks; the marks turn lit (the 'Okay' opening) row by row and slowly fall back,
# and a short trace on the right rises and falls as the cut-offs do. At t = 0 most marks are lit.
ICON = r"""(kit, t, tilt) => {
  const th = 5, T = Number(t) || 0, lit = .8 + .2 * Math.sin(T * .5);
  let out = kit.slab(44, 38, th);
  for (let r = 0; r < 5; r++) for (let c = 0; c < 6; c++) {
    const u = -34 + c * 8.4, v = -22 + r * 9.5, on = (r * 6 + c) / 30 < lit;
    out += kit.line(kit.at(u - 1.6, v, th / 2), kit.at(u + 1.6, v, th / 2), 3, on ? "lit" : "plain", on ? 1 : .8);
  }
  const ys = [8, -6, -4, 18], xs = [20, 26, 32, 38];
  for (let i = 0; i + 1 < xs.length; i++) out += kit.line(kit.at(xs[i], ys[i] - 4, th / 2), kit.at(xs[i + 1], ys[i + 1] - 4, th / 2), 1.6, "plain", 1);
  return out;
}"""

PAGE = PAGE.replace("__TITLE__", TITLE).replace("__CONFIG__", json.dumps({
    "problem": PROBLEM, "line": LINE, "panels": PANELS, "problems": PROBLEMS, "problems1": PROBLEMS1,
    "data": {"n": DATA["n"], "cap": DATA["cap"], "right": [DATA["right"], DATA["t10"]["right"]],
             "samples": [None] + [DATA["t10"]["four"]["samples"][k] for k in KEYS[1:]]}}))

if __name__ == "__main__":  # run from the repository root
    problems, extra, rows = _build()
    problems1, extra1 = _build1()
    if sys.argv[1:] == ["--write"]:
        src = open(__file__).read()
        for name, rs in (("PROBLEMS = ", problems), ("PROBLEMS1 = ", problems1)):
            start = src.index("\n" + name) + 1
            end = src.index("\n\n", start)
            src = src[:start] + name + "[\n" + "".join("    " + json.dumps(r, ensure_ascii=False) + ",\n" for r in rs) + "]" + src[end:]
        open(__file__, "w").write(src)
        sys.exit(f"wrote {len(problems)} and {len(problems1)} problems; from the rows: {extra}")
    assert PROBLEMS == problems, "PROBLEMS differs from the rows: run with --write"
    assert PROBLEMS1 == problems1, "PROBLEMS1 differs from the rows: run with --write"
    for key in ("right", "okay400", "median_len", "median_lp"):
        assert DATA[key] == extra[key], (key, extra[key])
    col = lambda k, test: sum(test(p, KEYS.index(k)) for p in PROBLEMS)
    for k in KEYS:
        i = KEYS.index(k)
        assert col(k, lambda p, i: p[4][i] == "1") == DATA["okay"][i], k
        assert col(k, lambda p, i: p[3][i] == "c") == DATA["cut"][i], k
        assert sum(r["cap_hit"] for r in rows[k].values()) - sum(x for x, p in zip(extra["v3"][k], PROBLEMS) if p[3][i] == "c") \
            == DATA["cut"][i] - DATA["right_cut"][i], k
    # the committed outputs of the round and of the grader
    load = lambda path: json.load(open(path))
    cc = json.loads(open(DATA["capcounts"]).read())
    assert [cc[m]["math500"]["cap_hits"] for m in ("base", "s0100", "s0400", "s2800")] == [DATA["cut"][i] for i in (0, 2, 3, 4)]
    t2 = load(DATA["turn2"])["median_mean_logprob_finished"]
    assert [round(t2[m], 3) for m in ("plain_base", "cued_base", "step100", "step400", "step2800")] == DATA["median_lp"]
    m10 = load(DATA["metrics"])["theories"]["r4-m10"]["rows"]
    assert round(m10[0]["measured"] * DATA["n"]) == DATA["okay"][2]  # turn 1, test 1: share of step-100 answers opening 'Okay'
    gr = load(DATA["grader"])["cells"]
    assert (gr["base_plain_0.6"]["right_v3"], gr["base_opener_0.6"]["right_v3"]) == tuple(DATA["right"][:2])
    assert (gr["base_plain_0.6"]["cap_hits_right_v3"], gr["base_opener_0.6"]["cap_hits_right_v3"]) == tuple(DATA["right_cut"][:2])
    assert [col(k, lambda p, i: p[3][i] == "r") for k in KEYS] == [r - c for r, c in zip(DATA["right"], DATA["right_cut"])]
    p1 = next(p for p in load(DATA["theory_test"])["predictions"] if p["k"] == 1)
    assert [p1["value"], p1["low"], p1["high"]] == DATA["predicted"]["theory"] and round(p1["measured"], 3) == DATA["predicted"]["measured"]
    readers = [next(json.loads(x) for x in open(f) if '"r4-m10:p1"' in x)["value"] for f in DATA["readers"]]
    assert readers == DATA["predicted"]["readers"], readers
    base_ok = {p[0] for p in PROBLEMS if p[4][0] == "1"}
    for k in ("base", "cue"):
        i = KEYS.index(k)
        assert [[sum(p[3][i] == "c" for p in PROBLEMS if (p[0] in base_ok) == side), sum((p[0] in base_ok) == side for p in PROBLEMS)]
                for side in (True, False)] == DATA["by_opening"][k], k
    from studies.rlneurons.lib import n13_score
    s100, cue = extra["v3"]["s100"], extra["v3"]["cue"]
    lo, hi = n13_score.paired_bootstrap(s100, cue, n_boot=5000, seed=0)  # in points of 500 problems
    assert [sum(s100) - sum(cue), round(lo * DATA["n"] / 100), round(hi * DATA["n"] / 100)] == \
        [DATA["s100_vs_cue"]["diff"], *DATA["s100_vs_cue"]["ci"]], (lo, hi)

    # T 1.0: PROBLEMS1 against the committed per-problem rows, the ckptcue readout and the grader's readout
    import numpy as np
    T, r1 = DATA["t10"], extra1["right"]
    assert [p[0] for p in PROBLEMS1] == [p[0] for p in PROBLEMS] == list(range(DATA["n"]))
    col1 = lambda i, test: sum(test(p) for p in PROBLEMS1)
    for i, k in enumerate(KEYS):
        assert col1(i, lambda p: p[2][i] == "1") == T["okay"][i], k
        assert col1(i, lambda p: p[1][i] == "c") == T["cut"][i], k
        assert sum(r1[k]) == T["right1"][i], k
        assert sum(x for x, p in zip(r1[k], PROBLEMS1) if p[1][i] == "c") == T["right_cut"][i], k
        assert col1(i, lambda p: p[1][i] == "r") == T["right1"][i] - T["right_cut"][i], k
    assert [sum(r1[k]) for k in ("s100cue", "s400cue")] == T["cue_steps"]["right"]
    assert [col1(i, lambda p: p[1][i] == "c") for i in (5, 6)] == T["cue_steps"]["cut"]
    assert extra1["t2_v3"] == r1["s2800"]
    ro = load(T["readout"])
    cells = ro["cells"]
    assert [cells[c]["right"] for c in ("base_cue_T1", "s0100_plain", "s0400_plain", "rl_final_T2")] == T["right1"][1:]
    assert [cells[c]["right"] for c in ("s0100_cue", "s0400_cue")] == T["cue_steps"]["right"]
    assert [cells[c]["cap_hits"] for c in ("s0100_plain", "s0400_plain")] == T["cut"][2:4]
    assert [cells[c]["cap_hits"] for c in ("s0100_cue", "s0400_cue")] == T["cue_steps"]["cut"]
    assert [cells[c]["okay_in_first_30"] for c in ("s0100_plain", "s0400_plain")] == T["okay"][2:4]
    g1 = load(DATA["grader"])
    for i, c in ((0, "base_plain_1.0"), (1, "base_opener_1.0"), (4, "rl_1.0")):
        assert (g1["cells"][c]["right_v3"], g1["cells"][c]["cap_hits"], g1["cells"][c]["cap_hits_right_v3"]) == \
            (T["right1"][i], T["cut"][i], T["right_cut"][i]), c
    assert hashlib.sha256(open(ROWS1 + T["raw"]["s2800"], "rb").read()).hexdigest() == g1["files"]["rl_1.0"]["sha256"]
    x = {k: np.array(v) for k, v in r1.items()}
    for (p, q), want, name in ((("s100", "cue"), T["s100_vs_cue1"], "s0100_plain minus base_cue_T1"),
                               (("s100cue", "s100"), T["cue_gain"]["s100"], "s0100_cue minus s0100_plain"),
                               (("s400cue", "s400"), T["cue_gain"]["s400"], "s0400_cue minus s0400_plain")):
        lo, hi = n13_score.paired_bootstrap(x[p], x[q], n_boot=5000, seed=0)
        got = [round(100 * (x[p].mean() - x[q].mean()), 1), round(lo, 1), round(hi, 1)]
        assert got == want, (p, q, got)
        rd = ro["differences"][name]
        assert [round(rd["points"], 1), *[round(v, 1) for v in rd["ci95"]]] == want, name

    # T 1.0, four samples: recomputed from the rows (sample 0 of steps 100 and 400 from the cells' per_problem.json) and
    # compared with readout3.json
    F, M = T["four"], {}
    for k, path in F["rows"].items():
        m = np.full((4, DATA["n"]), np.nan)
        if k in T["cells"]:
            for r in extra1["ck"][k]:
                m[0, r["problem_index"]] = r["score_v3"]
        rows4 = [r for r in map(json.loads, open(path)) if r["attempt"] == 0]
        assert len(rows4) == (2000 if k in ("cue", "s2800") else 1500), k
        for r in rows4:
            assert np.isnan(m[r["sample"], r["problem_index"]]), (k, r["sample"], r["problem_index"])
            m[r["sample"], r["problem_index"]] = r["score_v3"]
        assert not np.isnan(m).any(), k
        M[k] = m.mean(0)
        assert m.sum(1).astype(int).tolist() == F["samples"][k], (k, m.sum(1))
    r3 = load(F["readout"])
    cell3 = {"cue": "base_cue", "s100": "s0100_plain", "s100cue": "s0100_cue", "s400": "s0400_plain", "s2800": "rl_final"}
    for k, c in cell3.items():
        assert [x["right"] for x in r3["cells"][c]["samples"]] == F["samples"][k], k
        assert r3["cells"][c]["mean_right"] == sum(F["samples"][k]) / 4 == DATA["n"] * M[k].mean(), k
    assert T["right"] == [T["right1"][0]] + [sum(F["samples"][k]) / 4 for k in KEYS[1:]]
    for name, (p, q) in (("s100-cue", ("s100", "cue")), ("s100cue-s100", ("s100cue", "s100")), ("s100cue-cue", ("s100cue", "cue")),
                         ("s400-s100", ("s400", "s100")), ("s2800-s400", ("s2800", "s400"))):
        lo, hi = n13_score.paired_bootstrap(M[p], M[q], n_boot=5000, seed=0)
        got = [round(100 * (M[p].mean() - M[q].mean()), 2), round(lo, 2), round(hi, 2)]
        assert got == F["diff"][name], (name, got)
        rd = r3["differences"][f"{cell3[p]} minus {cell3[q]}"]
        assert [round(rd["points"], 2), *[round(v, 2) for v in rd["ci95"]]] == got, name
    assert T["s100_vs_cue"] == F["diff"]["s100-cue"]
    rt = T["right"]
    assert T["gap"] == [rt[4] - rt[1], rt[2] - rt[1], rt[3] - rt[2], rt[4] - rt[3]]
    assert F["band"] == [-3, 3] and "inside [-3, +3] points" in open(F["spec"]).read()
    a, lo, hi = F["predicted_s100"]
    assert f"step 100 plain {a} [{lo}, {hi}]" in open(F["spec"]).read()
    assert sum(r["opening"].startswith(" and resubmit.") for r in extra1["ck"]["s400"]) == T["resubmit"]
    a, lo, hi = T["predicted_s100"]
    assert f"step 100 plain {a} [{lo}, {hi}]" in open(T["spec"]).read()
    print("DATA, PROBLEMS and PROBLEMS1 match the rows in", ROWS, ROWS1, "and", DATA["capcounts"], DATA["turn2"],
          DATA["metrics"], DATA["grader"], T["readout"], T["t1_t3"], T["t1_t2"], *T["cells"].values(), F["readout"],
          *F["rows"].values())
